import {CloudError} from './cloud-malva.mjs';
import {memoryReviewError} from './memory-review-failure.mjs';
const metrics=['spend','revenueNet','adCosts','productCost','saleTax','frontOrders','orders','checkouts','linkClicks','impressions','dailyBudget'];
/** Addresses are regenerated from the final, frozen model packet. No numbers are generated by the model. */
export function cloudEvidenceReferences(context){
 const index=new Map();
 for(const [i,c] of (context.campaigns||[]).entries()){
  const add=(ref,row,period,level)=>{if(!row||!metrics.some(k=>Number.isFinite(row[k])))return;index.set(ref,{row,period,level,adAccountId:c.target.adAccountId,externalId:level==='campaign'?c.target.externalId:row.externalId,campaignExternalId:c.target.externalId});};
  for(const [period,row] of Object.entries(c.windows||{}))add(`C${i}/P/${period}`,row,period,'campaign');
  for(const [h,cut] of (c.hierarchy||[]).entries())for(const [r,row] of (cut.rows||[]).entries())if(row.adAccountId===c.target.adAccountId&&['adset','ad'].includes(cut.level))add(`C${i}/H${h}/R${r}`,row,cut.period,cut.level);
 }
 return index;
}
export function referenceCitationSchema(index,childOnly=false){const refs=[...index].filter(([,v])=>!childOnly||v.level!=='campaign').map(([k])=>k);return refs.length?{type:'object',properties:{observation:{type:'string',enum:refs},metric:{type:'string',enum:metrics}},required:['observation','metric'],additionalProperties:false}:{type:'object',properties:{},additionalProperties:false};}
export function referenceExamples(examples,index,account){return (examples||[]).flatMap(c=>{const found=[...index].find(([,v])=>v.adAccountId===(c.adAccountId||account)&&v.externalId===c.externalId&&v.period===c.period&&v.level===c.level&&Number.isFinite(v.row[c.metric])&&v.row[c.metric]===c.value);return found?[{observation:found[0],metric:c.metric}]:[];});}
/** Selectors are resolved only against data actually sent, then existing exact numeric validation runs again. */
export function resolveEvidenceReferences(raw,index){
 const out=structuredClone(raw),receipts=[];
 const resolve=(c,reading,scope,position)=>{
  if(!c||typeof c!=='object'||!Object.hasOwn(c,'observation'))return c;
  const found=index.get(c.observation),code=reading?'CLOUD_CAMPAIGN_READING_EVIDENCE':scope==='memoryReview'?'CLOUD_MEMORY_REVIEW_EVIDENCE':'CLOUD_REFLECTION_CITATION';
  if(Object.keys(c).length!==2||!Object.hasOwn(c,'metric')||!metrics.includes(c.metric)||!found||!Number.isFinite(found.row[c.metric])||reading&&(found.adAccountId!==reading.adAccountId||found.campaignExternalId!==reading.externalId)){
   if(scope==='memoryReview')throw memoryReviewError(Object.keys(c).length!==2||!Object.hasOwn(c,'metric')?'reference_shape':'reference_not_in_packet',position);
   const error=new CloudError(code);if(reading)error.readingFailure={adAccountId:reading.adAccountId,externalId:reading.externalId,reason:'citation_not_in_packet'};throw error;
  }
  receipts.push({scope,position,observation:c.observation,metric:c.metric});
  return {period:found.period,level:found.level,...(!reading?{adAccountId:found.adAccountId}:{}),externalId:found.externalId,metric:c.metric,value:found.row[c.metric]};
 };
 if(Array.isArray(out?.reflection?.citations))out.reflection.citations=out.reflection.citations.map((c,i)=>resolve(c,null,'reflection',i));
 for(const [i,reading] of (Array.isArray(out?.campaignReadings)?out.campaignReadings:[]).entries())if(Array.isArray(reading.citations))reading.citations=reading.citations.map((c,j)=>resolve(c,reading,'campaign:'+i,j));
 // The model names the same observation/metric it actually cited in its own reflection.
 // Only the server resolves its array position. This does not add or repair a citation.
 if(out?.memoryReview&&Object.hasOwn(out.memoryReview,'evidenceReferences')){
  const review=out.memoryReview,refs=review.evidenceReferences,seen=new Set();
  if(Object.hasOwn(review,'evidenceIndices')||!Array.isArray(refs)||refs.length>8)throw memoryReviewError('references_format');
  review.evidenceIndices=refs.map((ref,i)=>{
   if(!ref||typeof ref!=='object'||!Object.hasOwn(ref,'observation'))throw memoryReviewError('reference_shape',i);
   const citation=resolve(ref,null,'memoryReview',i),matches=(Array.isArray(out.reflection?.citations)?out.reflection.citations:[]).flatMap((c,j)=>c&&['period','level','adAccountId','externalId','metric','value'].every(k=>c[k]===citation[k])?[j]:[]);
   if(!matches.length)throw memoryReviewError('not_in_reflection',i);
   if(matches.length>1)throw memoryReviewError('ambiguous_reflection',i);
   if(seen.has(matches[0]))throw memoryReviewError('duplicate_reference',i);
   seen.add(matches[0]);receipts.at(-1).reflectionIndex=matches[0];return matches[0];
  });
  delete review.evidenceReferences;
 }
 return {value:out,receipts};
}
